# Added new specifier classes

class Auto(object):
    """Placeholder for automatic type inference specifier."""
    def __repr__(self):
        return 'Auto()'

class Fill(object):
    """Specifies a default value to use when a target lookup fails."""
    def __init__(self, default):
        self.default = default
    def __repr__(self):
        return f'Fill({self.default!r})'

class Let(object):
    """Specifies a variable binding for use within a spec."""
    def __init__(self, var, val):
        self.var = var
        self.val = val
    def __repr__(self):
        return f'Let({self.var!r}, {self.val!r})'

# Alias ROOT to the root Path (T)
ROOT = T

# Add __repr__ to Coalesce
class Coalesce(object):
    """Coalesce objects specify fallback behavior for a list of subspecs.
    (existing implementation omitted for brevity)"
    def __repr__(self):
        cn = self.__class__.__name__
        return f'{cn}({self.spec!r})'

# Add __repr__ to Assign
class Assign(object):
    """The ``Assign`` specifier type enables glom to modify the target,
    performing a "deep-set" to mirror glom's original deep-get use case."""
    def __repr__(self):
        return f'Assign({self.path!r}, {self.val!r})'

# Invoke specifier
class Invoke(object):
    """Invoke a callable with pre-specified constants."""
    def __init__(self, fn, *constants):
        self.fn = fn
        self.constants = constants
    def __repr__(self):
        cn = self.__class__.__name__
        return f'{cn}({self.fn!r}, constants={self.constants!r})'
